/// 1 から limit までの整数を順に返す自作イテレータ (実装済み)。
pub struct UpTo {
    current: u32,
    limit: u32,
}

impl UpTo {
    pub fn new(limit: u32) -> Self {
        UpTo { current: 0, limit }
    }
}

impl Iterator for UpTo {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.current < self.limit {
            self.current += 1;
            Some(self.current)
        } else {
            None
        }
    }
}

/// (1..=limit) と (2..=limit) を zip した各ペアの積のうち、
/// 3 の倍数だけを合計して返します。
pub fn sum_of_products(limit: u32) -> u32 {
    UpTo::new(limit)
        .zip(UpTo::new(limit).skip(1))
        .map(|(a, b)| a * b)
        .filter(|x| x % 3 == 0)
        .sum()
}

