use std::cell::RefCell;

pub fn try_update(cell: &RefCell<i32>, value: i32) -> bool {
    match cell.try_borrow_mut() {
        Ok(mut guard) => {
            *guard = value;
            true
        }
        Err(_) => false,
    }
}

pub fn is_readable(cell: &RefCell<i32>) -> bool {
    cell.try_borrow().is_ok()
}

