use std::sync::Arc;
use std::thread;

pub fn parallel_min_max_sum(data: Vec<i32>) -> Option<(i32, i32, i64)> {
    if data.is_empty() {
        return None;
    }
    let shared = Arc::new(data);

    let d = Arc::clone(&shared);
    let min_handle = thread::spawn(move || *d.iter().min().unwrap());

    let d = Arc::clone(&shared);
    let max_handle = thread::spawn(move || *d.iter().max().unwrap());

    let d = Arc::clone(&shared);
    let sum_handle = thread::spawn(move || d.iter().map(|&x| x as i64).sum::<i64>());

    Some((
        min_handle.join().unwrap(),
        max_handle.join().unwrap(),
        sum_handle.join().unwrap(),
    ))
}

