use std::sync::mpsc;
use std::thread;

pub fn channel_sum(chunks: Vec<Vec<i64>>) -> i64 {
    let (tx, rx) = mpsc::channel();

    let handles: Vec<_> = chunks
        .into_iter()
        .map(|chunk| {
            let tx = tx.clone();
            thread::spawn(move || {
                let partial: i64 = chunk.iter().sum();
                tx.send(partial).unwrap();
            })
        })
        .collect();

    // 手元の Sender を手放す。これで「全スレッドの tx が drop された時点で
    // チャネルが閉じる」状態になる
    drop(tx);

    let total: i64 = rx.iter().sum();

    for handle in handles {
        handle.join().unwrap();
    }

    total
}

