use std::thread;

pub fn parallel_chunk_sum(data: &[i64], num_chunks: usize) -> i64 {
    if data.is_empty() {
        return 0;
    }
    let num_chunks = num_chunks.max(1);
    let chunk_size = data.len().div_ceil(num_chunks);

    // map: チャンクごとに部分和を計算するスレッドを起動
    let handles: Vec<_> = data
        .chunks(chunk_size)
        .map(|chunk| {
            let owned = chunk.to_vec();
            thread::spawn(move || owned.iter().sum::<i64>())
        })
        .collect();

    // reduce: 部分和を統合
    handles.into_iter().map(|h| h.join().unwrap()).sum()
}

