pub struct Node {
    pub value: i32,
    pub left: Option<Box<Node>>,
    pub right: Option<Box<Node>>,
}

/// 子を持たないノードを作る (実装済み)
pub fn leaf(value: i32) -> Option<Box<Node>> {
    node(value, None, None)
}

/// 左右の子つきのノードを作る (実装済み)
pub fn node(value: i32, left: Option<Box<Node>>, right: Option<Box<Node>>) -> Option<Box<Node>> {
    Some(Box::new(Node { value, left, right }))
}

pub fn height(root: &Option<Box<Node>>) -> usize {
    match root {
        None => 0,
        Some(n) => 1 + height(&n.left).max(height(&n.right)),
    }
}

pub fn count(root: &Option<Box<Node>>) -> usize {
    match root {
        None => 0,
        Some(n) => 1 + count(&n.left) + count(&n.right),
    }
}

description_md:
標準ライブラリの `vec!` に似たマクロ `my_vec!` を `macro_rules!` で自作します。

要件は次のとおりです。

- `my_vec![]` は空の `Vec` を返します
- `my_vec![a, b, c]` のようにカンマ区切りの式を 1 個以上受け取り、**書いた順のまま**要素が入った `Vec` を返します
- 渡した各式はそれぞれ 1 回だけ評価されます (`$( ... )*` の繰り返し展開で `push` を並べれば自然に満たせます)

```rust
