assert_eq!(v, vec![1, 2, 3]);

let e: Vec<i32> = my_vec![];
assert!(e.is_empty());

let calc = my_vec![2 + 3, 10 * 2];
assert_eq!(calc, vec![5, 20]);
```

ヒント: 引数のパターンは `$($x:expr),+` のように「式の繰り返し」で受けます。

