}

impl Score {
    /// 0 以上 100 以下なら Ok(Score) を、それ以外は Err を返します。
    pub fn new(value: u8) -> Result<Score, String> {
        if value <= 100 {
            Ok(Score { value })
        } else {
            Err(format!("スコアは 0 以上 100 以下で指定してください: {value}"))
        }
    }

    /// 保持している値を返します。
    pub fn value(&self) -> u8 {
        self.value
    }
}

