use std::borrow::Cow;

pub fn abs_all(nums: &[i32]) -> Cow<'_, [i32]> {
    if nums.iter().any(|&n| n < 0) {
        Cow::Owned(nums.iter().map(|n| n.abs()).collect())
    } else {
        Cow::Borrowed(nums)
    }
}

