answer_code:
pub fn add_with_carry(a: u8, b: u8, carry: bool) -> (u8, bool) {
    let (sum1, overflow1) = a.overflowing_add(b);
    let (sum2, overflow2) = sum1.overflowing_add(carry as u8);
    (sum2, overflow1 || overflow2)
}

pub fn add2(a: [u8; 2], b: [u8; 2]) -> ([u8; 2], bool) {
    let (lo, carry) = add_with_carry(a[0], b[0], false);
    let (hi, carry) = add_with_carry(a[1], b[1], carry);
    ([lo, hi], carry)
}

