use std::collections::HashMap;

/// 各単語の (出現回数, 初出の添字) を返す。
pub fn count_with_first_index(words: &[&str]) -> HashMap<String, (usize, usize)> {
    let mut map = HashMap::new();
    for (i, w) in words.iter().enumerate() {
        map.entry(w.to_string())
            .and_modify(|(count, _first)| *count += 1)
            .or_insert((1, i));
    }
    map
}

