use std::collections::HashMap;

/// 文字をソートした文字列をキーにして、アナグラムごとに単語をまとめる。
pub fn group_anagrams(words: &[&str]) -> HashMap<String, Vec<String>> {
    let mut groups: HashMap<String, Vec<String>> = HashMap::new();
    for w in words {
        let mut chars: Vec<char> = w.chars().collect();
        chars.sort_unstable();
        let key: String = chars.into_iter().collect();
        groups.entry(key).or_default().push(w.to_string());
    }
    groups
}

description_md:
昇順に整列済みの `Vec<i32>` に対して、**整列を保ったまま** 要素を挿入する関数 `sorted_insert` と、要素の有無を二分探索で調べる関数 `contains_sorted` を実装してください。

```rust
pub fn sorted_insert(v: &mut Vec<i32>, x: i32);
pub fn contains_sorted(v: &[i32], x: i32) -> bool;
```

仕様は次のとおりです。

- `sorted_insert`: `v` は昇順に整列済みであると仮定してよいです。`x` を挿入したあとも `v` は昇順に整列されていなければなりません。すでに同じ値がある場合も **削除せず** 挿入します(結果として同じ値が複数並びます)
- `contains_sorted`: `v` に `x` が含まれていれば `true` を返します

入出力例:

```rust
let mut v = vec![1, 3, 5, 7];
sorted_insert(&mut v, 4);
assert_eq!(v, vec![1, 3, 4, 5, 7]);
sorted_insert(&mut v, 0);
assert_eq!(v, vec![0, 1, 3, 4, 5, 7]);
sorted_insert(&mut v, 5);
assert_eq!(v, vec![0, 1, 3, 4, 5, 5, 7]);

let mut empty = Vec::new();
sorted_insert(&mut empty, 42);
assert_eq!(empty, vec![42]);

assert!(contains_sorted(&[1, 3, 5], 3));
assert!(!contains_sorted(&[1, 3, 5], 4));
assert!(!contains_sorted(&[], 1));
```

注意事項:

- スライスの `binary_search(&x)` は、見つかれば `Ok(位置)`、見つからなければ **「整列を保つために挿入すべき位置」** を `Err(位置)` として返します。この設計を活かすと線形探索なしで挿入位置が O(log n) で求まります

