/// 昇順整列済みの v に、整列を保ったまま x を挿入する。
pub fn sorted_insert(v: &mut Vec<i32>, x: i32) {
    let pos = match v.binary_search(&x) {
        Ok(pos) => pos,
        Err(pos) => pos,
    };
    v.insert(pos, x);
}

/// 昇順整列済みの v に x が含まれているかを二分探索で判定する。
pub fn contains_sorted(v: &[i32], x: i32) -> bool {
    v.binary_search(&x).is_ok()
}

