/// ASCII 大文字小文字を無視して連続する重複を除き、各グループの最初の要素を残す。
pub fn dedup_case_insensitive(mut v: Vec<String>) -> Vec<String> {
    v.dedup_by(|later, earlier| later.eq_ignore_ascii_case(earlier));
    v
}

