use std::borrow::Borrow;
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct UserId(pub String);

impl Borrow<str> for UserId {
    fn borrow(&self) -> &str {
        &self.0
    }
}

pub fn build_index(pairs: &[(&str, u32)]) -> HashMap<UserId, u32> {
    pairs
        .iter()
        .map(|(id, score)| (UserId(id.to_string()), *score))
        .collect()
}

pub fn lookup(map: &HashMap<UserId, u32>, id: &str) -> Option<u32> {
    map.get(id).copied()
}

