use std::error::Error;
use std::fmt;

#[derive(Debug)]
pub struct AppError {
    message: String,
    source: Option<Box<dyn Error + 'static>>,
}

impl AppError {
    pub fn new(message: &str) -> Self {
        AppError {
            message: message.to_string(),
            source: None,
        }
    }

    pub fn with_source(message: &str, source: Box<dyn Error + 'static>) -> Self {
        AppError {
            message: message.to_string(),
            source: Some(source),
        }
    }
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl Error for AppError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        self.source.as_deref()
    }
}

pub fn root_cause(err: &(dyn Error + 'static)) -> String {
    let mut current = err;
    while let Some(next) = current.source() {
        current = next;
    }
    current.to_string()
}

description_md:
`Box<dyn Error>` は「何らかのエラー」をまとめて扱える便利な型ですが、具象型の情報が消えているため、そのままでは `match` で種類ごとに分岐できません。`dyn Error` には `downcast_ref::<T>()` メソッドがあり、「実際の型が `T` なら `Some(&T)`」を返してくれます。これを使って型を取り戻し、エラーの種類に応じた処理を書けます。

次の 2 つの関数を実装してください。`NegativeError` 型 (`Display` / `Error` 実装済み) はそのまま使ってください。

1. `half(s: &str) -> Result<i32, Box<dyn Error>>`
   - `s` を `i32` として解析する。失敗したら `ParseIntError` を `Box<dyn Error>` として返す (`?` が使えます)
   - 値が負なら `Err(Box::new(NegativeError(値)))`
   - それ以外は `Ok(値 / 2)` (整数除算)
2. `classify(err: &(dyn Error + 'static)) -> String`
   - `err` の実体が `ParseIntError` なら `"parse"`
   - `NegativeError(n)` なら `"negative:{n}"` (例: `"negative:-4"`)
   - それ以外なら `"unknown"`

```rust
assert_eq!(half("10").unwrap(), 5);

let err = half("abc").unwrap_err();
assert_eq!(classify(err.as_ref()), "parse");

let err = half("-4").unwrap_err();
assert_eq!(classify(err.as_ref()), "negative:-4");

assert_eq!(classify(&std::fmt::Error), "unknown");
```

