    let err = half("-1").unwrap_err();
    assert_eq!(classify(&*err), "negative:-1");
}

#[test]
fn test_classify_unknown() {
    assert_eq!(classify(&std::fmt::Error), "unknown");
    let io = std::io::Error::new(std::io::ErrorKind::Other, "disk");
    assert_eq!(classify(&io), "unknown");
}

answer_code:
use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
pub struct NegativeError(pub i32);

impl fmt::Display for NegativeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "negative number: {}", self.0)
    }
}

impl Error for NegativeError {}

pub fn half(s: &str) -> Result<i32, Box<dyn Error>> {
    let n: i32 = s.parse()?;
    if n < 0 {
        return Err(Box::new(NegativeError(n)));
    }
    Ok(n / 2)
}

pub fn classify(err: &(dyn Error + 'static)) -> String {
    if err.downcast_ref::<ParseIntError>().is_some() {
        String::from("parse")
    } else if let Some(NegativeError(n)) = err.downcast_ref::<NegativeError>() {
        format!("negative:{}", n)
    } else {
        String::from("unknown")
    }
}

description_md:
Rust では `[i32; 3]` と `[i32; 5]` は **別の型** です。そのため `fn sum(arr: [i32; 3])` と書いた関数には長さ 5 の配列を渡せません。const generics を使うと、配列の長さ `N` を型パラメータのように扱い、任意の長さの配列を一つの関数で受け取れます。

```rust
fn sum<const N: usize>(arr: [i32; N]) -> i32
```

次の 2 つの関数を実装してください。

1. `sum<const N: usize>(arr: [i32; N]) -> i32` — 全要素の合計。空配列なら `0`
2. `min_max<const N: usize>(arr: [i32; N]) -> Option<(i32, i32)>` — `(最小値, 最大値)` を返す。空配列 (`N == 0`) なら `None`

```rust
assert_eq!(sum([1, 2, 3]), 6);
assert_eq!(sum([1, 2, 3, 4, 5]), 15);
let empty: [i32; 0] = [];
assert_eq!(sum(empty), 0);

assert_eq!(min_max([3, -1, 4, 1, 5]), Some((-1, 5)));
assert_eq!(min_max([7]), Some((7, 7)));
```

注意: 配列は値渡し (ムーブ) で受け取ります。`i32` は `Copy` なので呼び出し後も元の配列は使えます。

