pub fn sum<const N: usize>(arr: [i32; N]) -> i32 {
    arr.iter().sum()
}

pub fn min_max<const N: usize>(arr: [i32; N]) -> Option<(i32, i32)> {
    if N == 0 {
        return None;
    }
    let mut min = arr[0];
    let mut max = arr[0];
    for &x in arr.iter().skip(1) {
        if x < min {
            min = x;
        }
        if x > max {
            max = x;
        }
    }
    Some((min, max))
}

