use std::collections::VecDeque;

/// 無向グラフ上で start から各頂点への最短距離 (辺の本数) を BFS で求める。
/// 到達できない頂点は None
pub fn bfs_distances(n: usize, edges: &[(usize, usize)], start: usize) -> Vec<Option<usize>> {
    // 1. 隣接リストの構築 (無向なので両方向に追加)
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];
    for &(u, v) in edges {
        adj[u].push(v);
        adj[v].push(u);
    }

    // 2. 初期化
    let mut dist: Vec<Option<usize>> = vec![None; n];
    let mut queue = VecDeque::new();
    dist[start] = Some(0);
    queue.push_back(start);

    // 3. BFS: キューから取り出した順に距離が確定する
    while let Some(u) = queue.pop_front() {
        let d = dist[u].expect("キューに入っている頂点は距離が確定している");
        for &v in &adj[u] {
            if dist[v].is_none() {
                dist[v] = Some(d + 1);
                queue.push_back(v);
            }
        }
    }

    dist
}

