/// RPN 評価中に起こりうる失敗
#[derive(Debug, PartialEq)]
pub enum RpnError {
    /// 数値でも演算子でもないトークン (そのトークン文字列を保持)
    InvalidToken(String),
    /// 演算に必要なオペランドが足りない、または結果がちょうど 1 個にならない
    StackUnderflow,
    /// 0 で割ろうとした
    DivisionByZero,
}

/// 空白区切りの逆ポーランド記法の式を評価する
pub fn eval_rpn(input: &str) -> Result<i64, RpnError> {
    let mut stack: Vec<i64> = Vec::new();

    for token in input.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                // スタックの上が rhs、その下が lhs
                let rhs = stack.pop().ok_or(RpnError::StackUnderflow)?;
                let lhs = stack.pop().ok_or(RpnError::StackUnderflow)?;
                let result = match token {
                    "+" => lhs + rhs,
                    "-" => lhs - rhs,
                    "*" => lhs * rhs,
                    _ => {
                        if rhs == 0 {
                            return Err(RpnError::DivisionByZero);
                        }
                        lhs / rhs
                    }
                };
                stack.push(result);
            }
            _ => {
                let value = token
                    .parse::<i64>()
                    .map_err(|_| RpnError::InvalidToken(token.to_string()))?;
                stack.push(value);
            }
        }
    }

    match (stack.pop(), stack.is_empty()) {
        (Some(result), true) => Ok(result),
        _ => Err(RpnError::StackUnderflow),
    }
}

