```rust
let counts = word_count_parallel("apple banana apple cherry banana apple", 2);
assert_eq!(counts["apple"], 3);
assert_eq!(counts["banana"], 2);
assert_eq!(counts["cherry"], 1);

// スレッド数を変えても結果は同じ
assert_eq!(word_count_parallel("a b a", 1), word_count_parallel("a b a", 8));
```

