use std::collections::HashMap;
use std::thread;

/// text を単語に分割し、n_threads 個までのスレッドで並列に数えます。
pub fn word_count_parallel(text: &str, n_threads: usize) -> HashMap<String, usize> {
    // 1. 単語を所有権つきの Vec<String> にしておく (スレッドへ move できるように)
    let words: Vec<String> = text.split_whitespace().map(str::to_string).collect();
    if words.is_empty() {
        return HashMap::new();
    }

    // 2. ほぼ均等なチャンクに分け、チャンクごとにスレッドを起動する
    let chunk_size = words.len().div_ceil(n_threads.max(1));
    let handles: Vec<_> = words
        .chunks(chunk_size)
        .map(|chunk| {
            let chunk: Vec<String> = chunk.to_vec();
            thread::spawn(move || {
                let mut partial: HashMap<String, usize> = HashMap::new();
                for word in chunk {
                    *partial.entry(word).or_insert(0) += 1;
                }
                partial
            })
        })
        .collect();

    // 3. join して部分結果を Entry API でマージする
    let mut total: HashMap<String, usize> = HashMap::new();
    for handle in handles {
        let partial = handle.join().expect("worker thread panicked");
        for (word, count) in partial {
            *total.entry(word).or_insert(0) += count;
        }
    }
    total
}

