/// 内部イテレータ iter から step 個ごとに 1 要素を取り出すアダプタです。
pub struct StepBy<I> {
    iter: I,
    step: usize,
}

impl<I: Iterator> StepBy<I> {
    /// step は 1 以上。0 が渡された場合は panic します。
    pub fn new(iter: I, step: usize) -> Self {
        assert!(step >= 1, "step は 1 以上である必要があります");
        StepBy { iter, step }
    }
}

impl<I: Iterator> Iterator for StepBy<I> {
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        // 先頭の要素を取り出す。尽きていれば ? で None を返す
        let item = self.iter.next()?;
        // 次回のために step - 1 個を読み飛ばす (途中で尽きたら打ち切る)
        for _ in 0..self.step - 1 {
            if self.iter.next().is_none() {
                break;
            }
        }
        Some(item)
    }
}

