use std::ops::Add;

/// R 行 C 列の整数行列です。次元は型パラメータとして持ちます。
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Matrix<const R: usize, const C: usize> {
    pub data: [[i64; C]; R],
}

impl<const R: usize, const C: usize> Matrix<R, C> {
    pub fn new(data: [[i64; C]; R]) -> Self {
        Self { data }
    }

    /// 全要素 0 の行列を返します。
    pub fn zeros() -> Self {
        Self { data: [[0; C]; R] }
    }

    /// 転置行列 (R×C → C×R) を返します。
    pub fn transpose(&self) -> Matrix<C, R> {
        let mut data = [[0i64; R]; C];
        for r in 0..R {
            for c in 0..C {
                data[c][r] = self.data[r][c];
            }
        }
        Matrix { data }
    }
}

impl<const R: usize, const C: usize> Add for Matrix<R, C> {
    type Output = Matrix<R, C>;

    fn add(self, rhs: Self) -> Self::Output {
        let mut data = [[0i64; C]; R];
        for r in 0..R {
            for c in 0..C {
                data[r][c] = self.data[r][c] + rhs.data[r][c];
            }
        }
        Matrix { data }
    }
}

