/// i64 -> i64 の変換を順番に適用するパイプラインです。
pub struct Pipeline {
    stages: Vec<Box<dyn Fn(i64) -> i64>>,
}

impl Pipeline {
    /// 段が 1 つもないパイプラインを作ります。
    pub fn new() -> Pipeline {
        Pipeline { stages: Vec::new() }
    }

    /// 変換を末尾に追加します。
    pub fn add_stage<F: Fn(i64) -> i64 + 'static>(&mut self, f: F) {
        self.stages.push(Box::new(f));
    }

    /// 追加した順にすべての変換を適用します。段が 1 つもなければ入力をそのまま返します。
    pub fn run(&self, input: i64) -> i64 {
        self.stages.iter().fold(input, |acc, stage| stage(acc))
    }
}

