list.push_front(3);
list.push_front(2);
list.push_front(1);

let v: Vec<i32> = list.iter().copied().collect();
assert_eq!(v, vec![1, 2, 3]);

let mut sum = 0;
for x in list.iter() {
    sum += *x;
}
assert_eq!(sum, 6);

let empty: List<String> = List::new();
assert!(empty.iter().next().is_none());
```

