/// 単方向連結リストです。
pub struct List<T> {
    head: Option<Box<Node<T>>>,
}

struct Node<T> {
    value: T,
    next: Option<Box<Node<T>>>,
}

/// List の要素を先頭から順に参照 (&T) で返すイテレータです。
pub struct Iter<'a, T> {
    current: Option<&'a Node<T>>,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None }
    }

    /// 先頭に要素を追加します。
    pub fn push_front(&mut self, value: T) {
        let new_node = Box::new(Node {
            value,
            next: self.head.take(),
        });
        self.head = Some(new_node);
    }

    /// 先頭から走査するイテレータを返します。
    pub fn iter(&self) -> Iter<'_, T> {
        // Option<Box<Node<T>>> -> Option<&Node<T>>
        Iter {
            current: self.head.as_deref(),
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        // 現在のノードがなければ終了
        let node = self.current?;
        // 次のノードへ進める (Option<Box<Node<T>>> -> Option<&'a Node<T>>)
        self.current = node.next.as_deref();
        Some(&node.value)
    }
}

description_md:
HTTP リクエストの設定を組み立てる `RequestBuilder` を **型状態 (typestate) パターン** で実装してください。必須項目である `url` が設定されていない状態では `build` が **メソッドとして存在しない** ようにし、設定漏れを実行時ではなくコンパイル時に検出します。

## 要件

- マーカー型 `Missing` (url 未設定) と `Set` (url 設定済み) を用意し、`RequestBuilder<UrlState>` の型パラメータとして使います。`PhantomData<UrlState>` で状態を追跡します
- `RequestBuilder::new() -> RequestBuilder<Missing>`: 初期値は `method = "GET"`, `timeout_ms = 3000`, url 未設定
- `url(self, url: &str) -> RequestBuilder<Set>`: 必須項目を設定し、状態を `Set` に進めます (どの状態からでも呼べます)
- `method(self, method: &str) -> Self`, `timeout_ms(self, timeout_ms: u64) -> Self`: 任意項目。状態は変わらず、どの状態からでも呼べます
- `build(self) -> Request`: **`RequestBuilder<Set>` にだけ** 実装します。`Request { url, method, timeout_ms }` を返します
- 同じ項目を複数回設定した場合は、あとから設定した値が有効になります

`Request` は `pub url: String`, `pub method: String`, `pub timeout_ms: u64` を持ちます。

## 例

```rust
let req = RequestBuilder::new()
    .method("POST")
    .timeout_ms(500)
    .url("https://api.example.com/users")
    .build();
assert_eq!(req.url, "https://api.example.com/users");
assert_eq!(req.method, "POST");
assert_eq!(req.timeout_ms, 500);

// 既定値
let req = RequestBuilder::new().url("http://localhost").build();
assert_eq!(req.method, "GET");
assert_eq!(req.timeout_ms, 3000);

// url を設定せずに build するとコンパイルエラー
// let bad = RequestBuilder::new().method("GET").build();
// error[E0599]: no method named `build` found for struct `RequestBuilder<Missing>`
```

