use std::marker::PhantomData;

/// url が未設定であることを表すマーカー型です。
pub struct Missing;
/// url が設定済みであることを表すマーカー型です。
pub struct Set;

#[derive(Debug, PartialEq)]
pub struct Request {
    pub url: String,
    pub method: String,
    pub timeout_ms: u64,
}

/// UrlState は Missing か Set のどちらかです。
pub struct RequestBuilder<UrlState> {
    url: Option<String>,
    method: String,
    timeout_ms: u64,
    _state: PhantomData<UrlState>,
}

impl RequestBuilder<Missing> {
    /// method = "GET", timeout_ms = 3000 を初期値としてビルダーを作ります。
    pub fn new() -> RequestBuilder<Missing> {
        RequestBuilder {
            url: None,
            method: "GET".to_string(),
            timeout_ms: 3000,
            _state: PhantomData,
        }
    }
}

impl<S> RequestBuilder<S> {
    /// 必須項目 url を設定し、型状態を Set に進めます。
    pub fn url(self, url: &str) -> RequestBuilder<Set> {
        // 型パラメータが変わるので、フィールドを移しながら新しい値を作る
        RequestBuilder {
            url: Some(url.to_string()),
            method: self.method,
            timeout_ms: self.timeout_ms,
            _state: PhantomData,
        }
    }

    /// 任意項目。状態は変わりません。
    pub fn method(mut self, method: &str) -> Self {
        self.method = method.to_string();
        self
    }

    /// 任意項目。状態は変わりません。
    pub fn timeout_ms(mut self, timeout_ms: u64) -> Self {
        self.timeout_ms = timeout_ms;
        self
    }
}

impl RequestBuilder<Set> {
    /// url 設定済み (Set) のときだけ呼べます。
    pub fn build(self) -> Request {
        Request {
            // 型状態 Set に到達できるのは url() を通ったときだけなので、必ず Some
            url: self.url.expect("Set 状態では url は設定済み"),
            method: self.method,
            timeout_ms: self.timeout_ms,
        }
    }
}

description_md:
イベントが発生したら登録済みの購読者 (オブザーバー) 全員に通知する `EventBus` を実装してください。購読者は `Rc<dyn Observer>` として渡されますが、`EventBus` は **`Weak<dyn Observer>`** で保持し、購読者の寿命を延ばしたり循環参照を作ったりしないようにします。

## 要件

`Observer` トレイトと、イベント名を記録する購読者 `Logger` は用意されています。`EventBus` の次のメソッドを実装してください。

- `EventBus::new() -> EventBus`: 購読者のいないバスを作ります
- `subscribe(&self, observer: Rc<dyn Observer>)`: `Rc::downgrade` で `Weak` に変換して保持します。`&self` で呼べるように内部は `RefCell<Vec<Weak<dyn Observer>>>` です
- `publish(&self, event: &str)`: **生きている** (`upgrade` できる) 購読者に、登録順で `notify(event)` を呼びます。すでに drop された購読者はリストから取り除きます
- `subscriber_count(&self) -> usize`: いま生きている購読者の数を返します

注意: `RefCell` を `borrow` したまま `notify` を呼ぶと、購読者の実装によっては二重借用で panic します (`already borrowed`)。通知先を先に集めてから借用を手放し、そのあとで `notify` を呼ぶ構成にしてください。

## 例

```rust
let bus = EventBus::new();
let logger = Logger::new();          // Rc<Logger>
bus.subscribe(logger.clone());        // Rc<Logger> は Rc<dyn Observer> に自動変換される
bus.publish("start");
bus.publish("stop");
assert_eq!(*logger.events.borrow(), vec!["start".to_string(), "stop".to_string()]);
assert_eq!(bus.subscriber_count(), 1);

{
    let temp = Logger::new();
    bus.subscribe(temp.clone());
    assert_eq!(bus.subscriber_count(), 2);
}   // temp はここで drop される
assert_eq!(bus.subscriber_count(), 1);
bus.publish("after");                 // logger にだけ届く
```

