answer_code:
use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// イベント通知を受け取る購読者のインターフェースです。
pub trait Observer {
    fn notify(&self, event: &str);
}

/// 受け取ったイベント名を記録していく購読者の実装例です。
pub struct Logger {
    pub events: RefCell<Vec<String>>,
}

impl Logger {
    pub fn new() -> Rc<Logger> {
        Rc::new(Logger {
            events: RefCell::new(Vec::new()),
        })
    }
}

impl Observer for Logger {
    fn notify(&self, event: &str) {
        self.events.borrow_mut().push(event.to_string());
    }
}

/// 購読者を Weak で保持するイベントバスです。
pub struct EventBus {
    subscribers: RefCell<Vec<Weak<dyn Observer>>>,
}

impl EventBus {
    /// 購読者のいないバスを作ります。
    pub fn new() -> EventBus {
        EventBus {
            subscribers: RefCell::new(Vec::new()),
        }
    }

    /// 購読者を登録します。内部には Weak として保持します (所有しない)。
    pub fn subscribe(&self, observer: Rc<dyn Observer>) {
        self.subscribers.borrow_mut().push(Rc::downgrade(&observer));
        // observer (Rc) はここで drop されるが、呼び出し側が持つ Rc は残る
    }

    /// 生きている購読者全員に event を通知し、drop 済みの購読者は取り除きます。
    pub fn publish(&self, event: &str) {
        // 1. borrow_mut の中で「掃除」と「生きている Rc の収集」だけを行う
        let alive: Vec<Rc<dyn Observer>> = {
            let mut subs = self.subscribers.borrow_mut();
            subs.retain(|weak| weak.upgrade().is_some());
            subs.iter().filter_map(|weak| weak.upgrade()).collect()
        }; // ここで borrow が解放される

        // 2. 借用を手放してから通知する (notify 内で bus を触っても二重借用にならない)
        for observer in alive {
            observer.notify(event);
        }
    }

    /// いま生きている (upgrade できる) 購読者の数を返します。
    pub fn subscriber_count(&self) -> usize {
        self.subscribers
            .borrow()
            .iter()
            .filter(|weak| weak.upgrade().is_some())
            .count()
    }
}
